import assert from 'node:assert';
import { createState, step, frame, WIDTH, HEIGHT, COLLIDES_FILE_PATH } from '../game/neon.js';

// Since frame() takes a ctx, we need a mock ctx
const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  beginPath: () => {},
  fill: () => {},
  fillText: () => {},
};

function testD1() {
  console.log('Testing D1: No Bounce');
  const state = createState(1);
  // Position ball so it's about to hit the first brick from below
  // First brick: x = offsetX, y = BRICK_TOP
  // offsetX = (640 - (8 * (72 + 8) - 8)) / 2 = (640 - (8 * 80 - 8)) / 2 = (640 - 632) / 2 = 4
  // Brick 0: x=4, y=48, w=72, h=20
  state.ball.x = 10;
  state.ball.y = 48 + 20 + 7; // Just below the brick
  state.ball.vx = 0;
  state.ball.vy = -200; // Moving UP

  // Move ball into the brick
  const dt = 0.05;
  // state.ball.y will be 75 + (-200 * 0.05) = 65
  // 65 - 7 = 58. 58 is inside [48, 68].
  step(state, dt);

  console.log(`Ball position: ${state.ball.y}, vy: ${state.ball.vy}`);
  frame(mockCtx, state);

  console.log(`After frame, vy: ${state.ball.vy}`);
  assert.ok(state.ball.vy > 0, `Ball should have bounced (vy > 0), but is ${state.ball.vy}`);
}

try {
  testD1();
  console.log('D1 passed (which means the bug is fixed)');
} catch (e) {
  console.error('D1 failed (which is expected)');
  process.exit(1);
}

