// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Resolves collisions between the ball and the bricks.
// Returns true if at least one collision occurred.
export function resolveBrickCollisions(state) {
  const { ball, bricks } = state;
  let collided = false;

  for (const brick of bricks) {
    if (!brick.alive) continue;

    if (collides(ball, brick)) {
      collided = true;
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);

      const overlapX = Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
      const overlapY = Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);

      if (overlapX < overlapY) {
        ball.vx = -Math.sign(ball.vx) * Math.abs(ball.vx);
        ball.x = ball.vx > 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
      } else if (overlapY < overlapX) {
        ball.vy = -Math.sign(ball.vy) * Math.abs(ball.vy);
        ball.y = ball.vy > 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
      } else {
        // Corner hit
        ball.vx = -Math.sign(ball.vx) * Math.abs(ball.vx);
        ball.vy = -Math.sign(ball.vy) * Math.abs(ball.vy);
        if (ball.vx > 0) ball.x = brick.x - ball.r; else ball.x = brick.x + brick.w + ball.r;
        if (ball.vy > 0) ball.y = brick.y - ball.r; else ball.y = brick.y + brick.h + ball.r;
      }
      // We break to avoid "double inversion" on seams within the same frame
      // since the ball has been repositioned and its velocity changed.
      break;
    }
  }
  return collided;
}

